create type public.sales_agent_rpc_result as (id uuid, name text, phone text, is_active boolean, version integer);

alter table public.app_settings add column business_settings_version integer not null default 1 check (business_settings_version > 0), add column catalog_preferences_version integer not null default 1 check (catalog_preferences_version > 0), add column catalog_logo_version integer not null default 1 check (catalog_logo_version > 0);
