create or replace function public.prevent_app_settings_audit_record_id_change() returns trigger language plpgsql set search_path='' as $$ begin if new.audit_record_id is distinct from old.audit_record_id then raise exception using errcode='P0001',message='IMMUTABLE_FIELD'; end if; return new; end $$;
