create or replace function public.audit_configuration_sales(p_module text,p_entity_type text,p_entity_id uuid,p_operation text,p_actor text,p_device text,p_identifier text,p_field text,p_old text,p_new text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_action uuid; v_record_id uuid:=p_entity_id; begin if p_entity_type='app_settings' then select audit_record_id into v_record_id from public.app_settings where id=true; end if; insert into public.audit_actions(module,entity_type,entity_id,operation,actor_name,device_name,device_identifier) values(p_module,p_entity_type,v_record_id,p_operation,p_actor,p_device,p_identifier) returning id into v_action; insert into public.audit_logs(action_id,table_name,record_id,operation,field_name,old_value,new_value,actor_name,device_name,device_identifier) values(v_action,p_entity_type,v_record_id,'UPDATE',p_field,p_old,p_new,p_actor,p_device,p_identifier); return v_action; end $$;
