create or replace function public.create_sales_agent(p_command_id uuid,p_name text,p_phone text,p_actor_name text,p_device_name text,p_device_identifier text) returns public.sales_agent_rpc_result language plpgsql security definer set search_path='' as $$ declare v_hash bytea:=extensions.digest(convert_to(jsonb_build_object('operation','create_sales_agent','name',btrim(p_name),'phone',btrim(p_phone))::text,'UTF8'),'sha256'); v_id uuid; v_agent public.sales_agents%rowtype; begin insert into public.sales_agent_create_commands(command_id,payload_hash) values(p_command_id,v_hash) on conflict do nothing returning command_id into v_id; if v_id is null then select entity_id into v_id from public.sales_agent_create_commands where command_id=p_command_id for update; if (select payload_hash from public.sales_agent_create_commands where command_id=p_command_id)<>v_hash then raise exception using errcode='P0001',message='COMMAND_PAYLOAD_MISMATCH'; end if; if v_id is null or (select result_version from public.sales_agent_create_commands where command_id=p_command_id) is null then raise exception using errcode='P0001',message='COMMAND_INCOMPLETE'; end if; select * into v_agent from public.sales_agents where id=v_id; return (v_agent.id,v_agent.name,v_agent.phone,v_agent.is_active,v_agent.version)::public.sales_agent_rpc_result; end if; v_id:=extensions.gen_random_uuid(); if btrim(p_name)='' then raise exception using errcode='P0001',message='INVALID_INPUT'; end if; insert into public.sales_agents(id,name,phone,created_by,created_device_name,created_device_identifier) values(v_id,btrim(p_name),btrim(p_phone),p_actor_name,p_device_name,p_device_identifier) returning * into v_agent; update public.sales_agent_create_commands set entity_id=v_id,result_version=v_agent.version where command_id=p_command_id; perform public.audit_configuration_sales('sales','sales_agents',v_id,'CREATE',p_actor_name,p_device_name,p_device_identifier,'agent',null,v_agent.name); return (v_agent.id,v_agent.name,v_agent.phone,v_agent.is_active,v_agent.version)::public.sales_agent_rpc_result; end $$;

create or replace function public.update_sales_agent(p_agent_id uuid,p_name text,p_phone text,p_expected_version integer,p_actor_name text,p_device_name text,p_device_identifier text) returns public.sales_agent_rpc_result language plpgsql security definer set search_path='' as $$ declare v public.sales_agents%rowtype; begin update public.sales_agents set name=btrim(p_name),phone=btrim(p_phone),version=version+1,updated_by=p_actor_name,updated_device_name=p_device_name,updated_device_identifier=p_device_identifier where id=p_agent_id and version=p_expected_version returning * into v; if not found then if exists(select 1 from public.sales_agents where id=p_agent_id) then raise exception using errcode='P0001',message='VERSION_CONFLICT'; else raise exception using errcode='P0001',message='NOT_FOUND'; end if; end if; perform public.audit_configuration_sales('sales','sales_agents',v.id,'UPDATE',p_actor_name,p_device_name,p_device_identifier,'agent',null,v.name); return (v.id,v.name,v.phone,v.is_active,v.version)::public.sales_agent_rpc_result; end $$;

create or replace function public.activate_sales_agent(p_agent_id uuid,p_expected_version integer,p_actor_name text,p_device_name text,p_device_identifier text) returns public.sales_agent_rpc_result language plpgsql security definer set search_path='' as $$ declare v public.sales_agents%rowtype; begin update public.sales_agents set is_active=true,version=version+1,updated_by=p_actor_name,updated_device_name=p_device_name,updated_device_identifier=p_device_identifier where id=p_agent_id and version=p_expected_version returning * into v; if not found then if exists(select 1 from public.sales_agents where id=p_agent_id) then raise exception using errcode='P0001',message='VERSION_CONFLICT'; else raise exception using errcode='P0001',message='NOT_FOUND'; end if; end if; perform public.audit_configuration_sales('sales','sales_agents',v.id,'ACTIVATE',p_actor_name,p_device_name,p_device_identifier,'is_active','false','true'); return (v.id,v.name,v.phone,v.is_active,v.version)::public.sales_agent_rpc_result; end $$;

create or replace function public.deactivate_sales_agent(p_agent_id uuid,p_expected_version integer,p_actor_name text,p_device_name text,p_device_identifier text) returns public.sales_agent_rpc_result language plpgsql security definer set search_path='' as $$ declare v public.sales_agents%rowtype; v_action uuid; begin select * into v from public.sales_agents where id=p_agent_id for update; if not found then raise exception using errcode='P0001',message='NOT_FOUND'; end if; if v.version<>p_expected_version then raise exception using errcode='P0001',message='VERSION_CONFLICT'; end if; update public.sales_agents set is_active=false,version=version+1,updated_by=p_actor_name,updated_device_name=p_device_name,updated_device_identifier=p_device_identifier where id=p_agent_id returning * into v; v_action:=public.audit_configuration_sales('sales','sales_agents',v.id,'DEACTIVATE',p_actor_name,p_device_name,p_device_identifier,'is_active','true','false'); perform public.clear_selected_catalog_agent_internal(p_agent_id,v_action); return (v.id,v.name,v.phone,v.is_active,v.version)::public.sales_agent_rpc_result; end $$;

