alog_highlight_text_color,v.catalog_secondary_text_color,v.catalog_promotion_color,v.catalog_promotion_text_color,v.catalog_promotion_previous_price_color,v.catalog_promotion_price_color,v.catalog_promotion_description_color,v.catalog_image_fit,'catalog-logo',v.catalog_logo_version,v.selected_catalog_agent_id,v.catalog_preferences_version)::public.catalog_preferences_rpc_result; end $$;
