create or replace function public.create_packaging_presentation(
  p_command_id uuid, p_name text, p_actor_name text,
  p_device_name text, p_device_identifier text
) returns public.packaging_presentation_rpc_result
language plpgsql security definer set search_path = '' as $$
declare
  v_hash bytea := extensions.digest(convert_to(jsonb_build_object('operation','create_packaging_presentation','name',btrim(p_name))::text,'UTF8'),'sha256');
  v_id uuid;
  v public.packaging_presentations%rowtype;
begin
  insert into public.packaging_presentation_create_commands(command_id,payload_hash)
  values(p_command_id,v_hash) on conflict do nothing returning command_id into v_id;
  if v_id is null then
    select entity_id into v_id from public.packaging_presentation_create_commands where command_id=p_command_id for update;
    if (select payload_hash from public.packaging_presentation_create_commands where command_id=p_command_id) <> v_hash then raise exception using errcode='P0001',message='COMMAND_PAYLOAD_MISMATCH'; end if;
    if v_id is null or (select result_version from public.packaging_presentation_create_commands where command_id=p_command_id) is null then raise exception using errcode='P0001',message='COMMAND_INCOMPLETE'; end if;
    select * into v from public.packaging_presentations where id=v_id;
    return (v.id,v.name,v.sort_order,v.is_active,v.version)::public.packaging_presentation_rpc_result;
  end if;
  v_id := extensions.gen_random_uuid();
  insert into public.packaging_presentations(id,name,sort_order,created_by,created_device_name,created_device_identifier) values(v_id,btrim(p_name),(select count(*) from public.packaging_presentations),p_actor_name,p_device_name,p_device_identifier) returning * into v;
  update public.packaging_presentation_create_commands set entity_id=v_id,result_version=v.version where command_id=p_command_id;
  perform public.audit_configuration_sales('configuration','packaging_presentations',v.id,'CREATE',p_actor_name,p_device_name,p_device_identifier,'name',null,v.name);
  return (v.id,v.name,v.sort_order,v.is_active,v.version)::public.packaging_presentation_rpc_result;
exception when unique_violation then raise exception using errcode='P0001',message='DUPLICATE_PRESENTATION_NAME';
end;
$$;
create or replace function public.update_packaging_presentation(p_presentation_id uuid,p_name text,p_expected_version integer,p_actor_name text,p_device_name text,p_device_identifier text) returns public.packaging_presentation_rpc_result language plpgsql security definer set search_path='' as $$ declare v public.packaging_presentations%rowtype; begin update public.packaging_presentations set name=btrim(p_name),version=version+1,updated_by=p_actor_name,updated_device_name=p_device_name,updated_device_identifier=p_device_identifier where id=p_presentation_id and version=p_expected_version returning * into v; if not found then if exists(select 1 from public.packaging_presentations where id=p_presentation_id) then raise exception using errcode='P0001',message='VERSION_CONFLICT'; else raise exception using errcode='P0001',message='NOT_FOUND'; end if; end if; perform public.audit_configuration_sales('configuration','packaging_presentations',v.id,'UPDATE',p_actor_name,p_device_name,p_device_identifier,'name',null,v.name); return (v.id,v.name,v.sort_order,v.is_active,v.version)::public.packaging_presentation_rpc_result; exception when unique_violation then raise exception using errcode='P0001',message='DUPLICATE_PRESENTATION_NAME'; end $$;
revoke all on function public.create_packaging_presentation(uuid,text,text,text,text),public.update_packaging_presentation(uuid,text,integer,text,text,text) from public; grant execute on function public.create_packaging_presentation(uuid,text,text,text,text),public.update_packaging_presentation(uuid,text,integer,text,text,text) to anon,authenticated;

-- Storage byte replacement remains a 1B.4 concern. This registration validates
-- the canonical object but deliberately receives no client EXECUTE grant yet.
create or replace function public.register_catalog_logo_version(p_operation_id uuid,p_object_name text,p_mime_type text,p_expected_logo_version integer,p_actor_name text,p_device_name text,p_device_identifier text) returns public.catalog_logo_rpc_result language plpgsql security definer set search_path='' as $$ declare v_hash bytea:=extensions.digest(convert_to(jsonb_build_object('operation','register_catalog_logo','object_name',p_object_name,'mime_type',p_mime_type,'expected_version',p_expected_logo_version)::text,'UTF8'),'sha256'); v_version integer; v_actual_mime text; begin if p_object_name<>'catalog-logo' then raise exception using errcode='P0001',message='INVALID_INPUT'; end if; select coalesce(metadata->>'mimetype',metadata->>'contentType') into v_actual_mime from storage.objects where bucket_id='catalog-assets' and name='catalog-logo'; if not found then raise exception using errcode='P0001',message='NOT_FOUND'; end if; if v_actual_mime not in ('image/jpeg','image/png','image/webp') or v_actual_mime is distinct from p_mime_type then raise exception using errcode='P0001',message='INVALID_INPUT'; end if; insert into public.catalog_logo_operations(operation_id,payload_hash,object_name,result_version) values(p_operation_id,v_hash,p_object_name,0) on conflict do nothing; if not found then select result_version into v_version from public.catalog_logo_operations where operation_id=p_operation_id for update; if (select payload_hash from public.catalog_logo_operations where operation_id=p_operation_id)<>v_hash then raise exception using errcode='P0001',message='COMMAND_PAYLOAD_MISMATCH'; end if; return ('catalog-logo',v_version)::public.catalog_logo_rpc_result; end if; update public.app_settings set catalog_logo_version=catalog_logo_version+1 where id=true and catalog_logo_version=p_expected_logo_version returning catalog_logo_version into v_version; if not found then raise exception using errcode='P0001',message='VERSION_CONFLICT'; end if; update public.catalog_logo_operations set result_version=v_version where operation_id=p_operation_id; perform public.audit_configuration_sales('configuration','app_settings',null,'REGISTER_LOGO',p_actor_name,p_device_name,p_device_identifier,'catalog_logo_version',null,v_version::text); return ('catalog-logo',v_version)::public.catalog_logo_rpc_result; end $$;
revoke all on function public.register_catalog_logo_version(uuid,text,text,integer,text,text,text) from public,anon,authenticated;
